import collections

def get_divisors(n):
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return divs

def bfs_min_turns(F, S, max_turns=50, max_state_magnitude=10000):
    """
    Calculates the minimum turns to reach F from S.
    Returns turns if reachable within limits, else infinity/None.
    """
    if S == F:
        return 0

    queue = collections.deque([(S, 0)])
    visited = {S: 0}

    while queue:
        N, T = queue.popleft()

        if T >= max_turns:
            continue

        # 1. Find allowed choices X: divisors or multiples of N, X != 1

        # Divisors (including N itself)
        divisors = get_divisors(N)
        allowed_X = divisors - {1}

        # Multiples: Since we must limit the search space, we prioritize small multiples
        # We only check multiples k*N where k is small enough such that k*N +/- 1 
        # doesn't drastically exceed max_state_magnitude relative to F.
        # For now, let's limit k based on magnitude to prevent immediate blowup.

        k = 2
        while True:
            multiple = k * N
            # Heuristic pruning: If the multiple is too large, stop generating multiples
            if multiple > max_state_magnitude + 5: # Small buffer
                break
            allowed_X.add(multiple)
            k += 1

        # 2. Generate next states N'
        next_states = set()
        for X in allowed_X:
            # Organizer adds or subtracts 1
            N_plus = X + 1
            N_minus = X - 1
            next_states.add(N_plus)
            next_states.add(N_minus)

        # 3. Process next states
        for N_prime in next_states:
            if N_prime == F:
                return T + 1

            # Pruning based on magnitude
            if abs(N_prime) > max_state_magnitude and F > 0:
                continue

            if N_prime not in visited:
                visited[N_prime] = T + 1
                queue.append((N_prime, T + 1))

    return float('inf')

